markdown = ["# GitHub search results"]
    for name in names:
        matches = keyword_search(f"{name} GitHub", 1)
        markdown.append(f"\n## {name}")
        if matches:
            match = matches[0]
            markdown.append(f"[{match.title}]({match.url})")
        else:
            markdown.append("No result returned.")
